        return typeof url==='string' && /^https:\/\/(?:www\.)?(?:mosfilm\.ru|youtube\.com|youtu\.be|rutube\.ru|vkvideo\.ru|vk\.com)(?:\/|$)[^\s]*$/i.test(url);
