        var version=variant(source);
        if(!Object.prototype.hasOwnProperty.call(variantLabels,version))return {name:name,available:false,reason:'Эта версия источника пока не поддерживается.'};
        if(variantLabels[version])name+=' · '+variantLabels[version];
        if(!evidence(source.evidenceUrl)) return {name:name, available:false, reason:'Источник пока не подтверждён.'};
        if(source.provider!=='youtube' && source.provider!=='rutube') return {name:name, available:false, reason:name+' пока не поддерживается внутри этого плагина.'};
