            var data=L.Player.playdata(),token=launchToken,root=L.Player.render();
            if(!data || data.url!==info.url || !root || typeof root.append!=='function')return;
            var banner=$('<div class="mosfilm-playback-state" role="status" style="position:fixed;top:1em;left:1em;right:1em;z-index:12;padding:.6em .9em;border-radius:.4em;background:rgba(0,0,0,.8);color:#fff;font-size:.85em;line-height:1.4;pointer-events:none"></div>');
